+            IntVector va = IntVector.fromArray(SPECIES, a, i);
+            IntVector vb = IntVector.fromArray(SPECIES, b, i);
+            vall.lanewise(VectorOperators.XOR, va, vmask)
+                .lanewise(VectorOperators.XOR, vb, vmask)
+                .intoArray(r, i);
+        }
